package com.gameaggregator.billingservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;@Entity @Table(name="billing_plans") public class BillingPlan{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String code;@Column(nullable=false)public String cycle;@Column(nullable=false)public long usageQuota;@Column(nullable=false,precision=19,scale=6)public BigDecimal price;@Column(nullable=false)public String currency;protected BillingPlan(){}public BillingPlan(String c,String y,long q,BigDecimal p,String u){code=c;cycle=y;usageQuota=q;price=p;currency=u;}}